# Alonso Tadeo entró con las coordenadas publicadas; el punto entregado las reemplaza.
PUBLICADO_ALONSO_TADEO = (Decimal('0.601389'), Decimal('-78.130833'))


def dibujar_sedes(apps, schema_editor):
    Sede = apps.get_model('webcitt', 'SedeInstitucional')
    # Lo que ya se marcó o dibujó en el editor no se pisa.
    Sede.objects.filter(nombre='Sede matriz', contorno=[], edificios=[]).update(
        contorno=CONTORNO_MATRIZ,
        edificios=[{'nombre': nombre, 'contorno': vertices} for nombre, vertices in EDIFICIOS_MATRIZ],
    )
    for nombre, (latitud, longitud) in PUNTOS.items():
        sede = Sede.objects.filter(nombre=nombre).first()
        if sede and (sede.latitud is None or (sede.latitud, sede.longitud) == PUBLICADO_ALONSO_TADEO):
            sede.latitud, sede.longitud = latitud, longitud
            sede.save(update_fields=['latitud', 'longitud'])


